<p>public Map&lt;Integer, Integer&gt; mostFrequent(List&lt;Integer&gt; list){</p>
<pre><code> Map&lt;Integer, Integer&gt; freq = new HashMap();
</code></pre>
<pre><code>for (Integer n: list) {
</code></pre>
<pre><code>freq.merge(n, 1, Integer::sum);
</code></pre>
<p>}</p>
<pre><code>return freq.entrySet().stream()
        .max(Map.Entry.comparingByValue())
        .map(e -&gt; Map.of(e.getKey(), e.getValue()))
        .orElse(Map.of());
}
